import { validateSubtitleTrack, type SubtitleTrack } from '../src/shared/subtitles.js';

/** ASS is generated by the main process; user input never becomes filter arguments. */
const ASS_STYLES: Record<SubtitleTrack['preset'], string> = {
  // Name, Font, Size, Primary, Secondary, Outline, Back, Bold, Italic,
  // Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle,
  // Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding
  classic: 'Classic,Arial,48,&H00FFFFFF,&H00FFFFFF,&H00000000,&H80000000,-1,0,0,0,100,100,0,0,1,3,1,2,42,42,148,1',
  bold: 'Bold,Arial,60,&H0000E5FF,&H0000E5FF,&H00000000,&H80000000,-1,0,0,0,100,100,0,0,1,4,2,2,42,42,150,1',
  minimal: 'Minimal,Arial,40,&H00FFFFFF,&H00FFFFFF,&H00181818,&H80000000,0,0,0,0,100,100,0,0,1,2,0,2,48,48,170,1',
  boxed: 'Boxed,Arial,46,&H00FFFFFF,&H00FFFFFF,&H00000000,&H390F0F0F,-1,0,0,0,100,100,0,0,3,12,0,2,45,45,155,1',
};
const STYLE_NAMES: Record<SubtitleTrack['preset'], string> = {
  classic: 'Classic', bold: 'Bold', minimal: 'Minimal', boxed: 'Boxed',
};

function assTime(seconds: number): string {
  const cs = Math.round(seconds * 100);
  const hours = Math.floor(cs / 360000);
  const minutes = Math.floor((cs % 360000) / 6000);
  const secs = Math.floor((cs % 6000) / 100);
  return hours + ':' + String(minutes).padStart(2, '0') + ':' +
    String(secs).padStart(2, '0') + '.' + String(cs % 100).padStart(2, '0');
}

function assText(text: string): string {
  // Prevent untrusted ASS override tags, line breaks or control syntax.
  return text.replace(/\\/g, '＼').replace(/\{/g, '｛').replace(/\}/g, '｝')
    .replace(/\r\n?/g, '\n').replace(/\n/g, '\\N');
}

export function buildAss(track: SubtitleTrack, clipSeconds: number): string {
  const checked = validateSubtitleTrack(track, clipSeconds);
  if (!checked) throw new Error('자막 데이터가 없습니다.');
  const style = STYLE_NAMES[checked.preset];
  const events = [...checked.cues].sort((a, b) => a.start - b.start).map((cue) =>
    'Dialogue: 0,' + assTime(cue.start) + ',' + assTime(cue.end) + ',' + style +
    ',,0,0,0,,' + assText(cue.text));
  return [
    '[Script Info]', 'ScriptType: v4.00+', 'PlayResX: 720', 'PlayResY: 1280',
    'WrapStyle: 0', 'ScaledBorderAndShadow: yes', '',
    '[V4+ Styles]',
    'Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding',
    ...Object.values(ASS_STYLES).map((value) => 'Style: ' + value),
    '', '[Events]', 'Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text',
    ...events, '',
  ].join('\n');
}
